<?php
namespace App\Http\Controllers\Api\V1;
use App\Application\Payment\{CompleteSimulationPaymentAction,FailSimulationPaymentAction}; use App\Contracts\PaymentGateway; use App\Exceptions\ApiProblem; use App\Http\Controllers\Controller; use App\Http\Requests\Payment\SimulatePaymentRequest; use App\Models\{Booking,Payment}; use Illuminate\Http\{JsonResponse,Request}; use Illuminate\Support\Str;
final class PaymentController extends Controller {
    public function store(Request $request,Booking $booking,PaymentGateway $gateway): JsonResponse { if($booking->user_id!==$request->user()->id) throw new ApiProblem('FORBIDDEN','This booking does not belong to you.',403); if($booking->status!=='pending_payment') throw new ApiProblem('BOOKING_NOT_PAYABLE','This booking cannot be paid.',409); $key=(string)($request->header('Idempotency-Key') ?: 'WEB-'.$booking->id.'-'.Str::uuid()); $payment=$gateway->initiate($booking,$key); return response()->json(['data'=>$this->serialize($payment)],201); }
    public function simulate(SimulatePaymentRequest $request,Payment $payment,CompleteSimulationPaymentAction $complete,FailSimulationPaymentAction $fail): JsonResponse { if($payment->booking->user_id!==$request->user()->id) throw new ApiProblem('FORBIDDEN','This payment does not belong to you.',403); if($payment->provider!=='simulation') throw new ApiProblem('SIMULATION_ONLY','This endpoint only supports simulation payments.',409); $payment=$request->string('outcome')->toString()==='success'?$complete->execute($payment):$fail->execute($payment,$request->string('outcome')->toString()); return response()->json(['data'=>$this->serialize($payment)]); }
    private function serialize(Payment $p): array { return ['id'=>$p->id,'public_id'=>$p->public_id,'booking_id'=>$p->booking_id,'provider'=>$p->provider,'provider_transaction_id'=>$p->provider_transaction_id,'amount'=>$p->amount,'currency'=>$p->currency,'status'=>$p->status,'paid_at'=>$p->paid_at?->toIso8601String()]; }
}
